import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String assetType = request.getParameter("type");
        String sortCol = request.getParameter("sort");
        String direction = request.getParameter("dir");
        String limit = request.getParameter("limit");

        // Input validation for known-safe values
        if (assetType == null || assetType.isEmpty()) {
            assetType = "hardware";
        }
        if (direction == null || (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC"))) {
            direction = "ASC";
        }
        if (limit == null || !limit.matches("\\d+")) {
            limit = "50";
        }

        // Build query - sortCol is used for dynamic ORDER BY
        // Note: PreparedStatement cannot parameterize ORDER BY columns
        String query = "SELECT asset_id, asset_name, asset_type, location, status " +
                       "FROM inventory.assets WHERE asset_type = ? ";

        if (sortCol != null && !sortCol.isEmpty()) {
            // Developer attempted allowlist but used contains() instead of equals()
            String[] allowed = {"asset_id", "asset_name", "asset_type", "location", "status"};
            boolean valid = false;
            for (String col : allowed) {
                if (sortCol.contains(col)) {
                    valid = true;
                    break;
                }
            }
            if (valid) {
                query += "ORDER BY " + sortCol + " " + direction + " ";
            }
        }
        query += "LIMIT " + limit;

        logger.info("Executing asset search: type=" + assetType + ", sort=" + sortCol);

        response.setContentType("application/json");
        PrintWriter out = response.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, assetType);
            ResultSet rs = stmt.executeQuery();

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"asset_id\": \"").append(rs.getString("asset_id")).append("\", ");
                json.append("\"asset_name\": \"").append(rs.getString("asset_name")).append("\", ");
                json.append("\"asset_type\": \"").append(rs.getString("asset_type")).append("\", ");
                json.append("\"location\": \"").append(rs.getString("location")).append("\", ");
                json.append("\"status\": \"").append(rs.getString("status")).append("\"");
                json.append("}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            response.setStatus(500);
            out.print("{\"error\": \"Internal server error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        // POST delegates to GET for search
        doGet(request, response);
    }
}
